export const alphabet=m=>[...new Set(m.edges.map(e=>e.read).filter(Boolean))].sort();
export function validate(m,requireInitial=true){if(!m||!['fa','pda','tm'].includes(m.type)||!Array.isArray(m.states)||!Array.isArray(m.edges))throw Error('invalidModel');if(m.states.length>150||m.edges.length>1500)throw Error('modelLimit');let ids=new Set();for(const s of m.states){if(typeof s.id!=='string'||ids.has(s.id)||!Number.isFinite(s.x)||!Number.isFinite(s.y)||typeof s.name!=='string')throw Error('invalidModel');ids.add(s.id)}for(const e of m.edges){if(!ids.has(e.from)||!ids.has(e.to)||typeof e.read!=='string'||[...e.read].length>1)throw Error('invalidModel');if(m.type==='pda'&&(typeof e.pop!=='string'||typeof e.push!=='string'))throw Error('invalidModel');if(m.type==='tm'&&(typeof e.write!=='string'||[...e.write].length!==1||!['L','R','S'].includes(e.move)))throw Error('invalidModel')}if(m.states.filter(s=>s.initial).length>1||(requireInitial&&m.states.filter(s=>s.initial).length!==1))throw Error('oneInitial');return m}
export function closure(m,seeds){const r=new Set(seeds),q=[...r];for(let i=0;i<q.length;i++)for(const e of m.edges)if(e.from===q[i]&&!e.read&&!r.has(e.to)){r.add(e.to);q.push(e.to)}return r}
