export function deterministic(m){return m.type==='fa'&&!m.edges.some(e=>!e.read)&&m.states.every(s=>alphabet(m).every(c=>m.edges.filter(e=>e.from===s.id&&e.read===c).length<=1))}
export function determinize(m){validate(m);if(m.type!=='fa')throw Error('finiteOnly');const sigma=alphabet(m),key=s=>JSON.stringify([...s].sort()),sets=[closure(m,m.states.filter(s=>s.initial).map(s=>s.id))],keys=new Map([[key(sets[0]),0]]),states=[],edges=[];for(let i=0;i<sets.length;i++){if(i>149)throw Error('modelLimit');const set=sets[i];states.push({id:'d'+i,name:'D'+i,x:170+(i%5)*155,y:200+Math.floor(i/5)*140,initial:i===0,final:m.states.some(s=>set.has(s.id)&&s.final)});for(const c of sigma){const dest=closure(m,m.edges.filter(e=>set.has(e.from)&&e.read===c).map(e=>e.to)),k=key(dest);if(!keys.has(k)){keys.set(k,sets.length);sets.push(dest)}edges.push({from:'d'+i,to:'d'+keys.get(k),read:c})}}return{type:'fa',states,edges}}
