export function grammarParse(text){if(text.length>10000)throw Error('modelLimit');const p=[];for(const line of text.split('\n').filter(x=>x.trim())){const a=line.split(/→|->/);if(a.length!==2||! /^[A-Z]$/.test(a[0].trim()))throw Error('grammarError');for(const rhs of a[1].split('|'))p.push({lhs:a[0].trim(),rhs:[...rhs.trim().replace(/ε|λ/g,'')]})}if(!p.length)throw Error('grammarError');return p}
