export function example(type='fa'){const states=[{id:'q0',name:'q0',x:220,y:270,initial:true,final:false},{id:'q1',name:'q1',x:490,y:270,initial:false,final:false},{id:'q2',name:'q2',x:760,y:270,initial:false,final:true}];if(type==='pda'){states[0].initial=false;states.unshift({id:'start',name:'start',x:100,y:130,initial:true,final:false});return{type,states,edges:[{from:'start',to:'q0',read:'',pop:'',push:'Z'},{from:'q0',to:'q0',read:'a',pop:'',push:'A'},{from:'q0',to:'q1',read:'b',pop:'A',push:''},{from:'q1',to:'q1',read:'b',pop:'A',push:''},{from:'q1',to:'q2',read:'',pop:'Z',push:''}]}};if(type==='tm')return{type,states:[states[0],states[2]],edges:[{from:'q0',to:'q0',read:'0',write:'1',move:'R'},{from:'q0',to:'q0',read:'1',write:'0',move:'R'},{from:'q0',to:'q2',read:'□',write:'□',move:'S'}]};return{type:'fa',states,edges:[{from:'q0',to:'q0',read:'0'},{from:'q0',to:'q1',read:'1'},{from:'q1',to:'q0',read:'0'},{from:'q1',to:'q2',read:'1'},{from:'q2',to:'q0',read:'0'},{from:'q2',to:'q2',read:'1'}]}}
