export function toGrammar(m){validate(m);if(m.type!=='fa'||m.states.length>26)throw Error('modelLimit');const start=m.states.find(s=>s.initial),states=[start,...m.states.filter(s=>s!==start)],names=new Map(states.map((s,i)=>[s.id,String.fromCharCode(65+i)]));if(m.edges.some(e=>/[A-Z|ε→\s]/.test(e.read)))throw Error('grammarError');return states.map(s=>{const rhs=m.edges.filter(e=>e.from===s.id).map(e=>e.read+names.get(e.to));if(s.final)rhs.push('ε');return `${names.get(s.id)} → ${[...new Set(rhs.length?rhs:[names.get(s.id)])].join(' | ')}`}).filter(Boolean).join('\n')}
