export function grammarToPDA(text){const p=grammarParse(text),states=[{id:'start',name:'start',x:180,y:270,initial:true,final:false},{id:'work',name:'work',x:490,y:270,initial:false,final:false},{id:'end',name:'end',x:800,y:270,initial:false,final:true}],terminals=[...new Set(p.flatMap(pr=>pr.rhs.filter(c=>!/[A-Z]/.test(c))))];if(terminals.includes('⊥'))throw Error('grammarError');const edges=[{from:'start',to:'work',read:'',pop:'',push:p[0].lhs+'⊥'},...p.map(pr=>({from:'work',to:'work',read:'',pop:pr.lhs,push:pr.rhs.join('')})),...terminals.map(c=>({from:'work',to:'work',read:c,pop:c,push:''})),{from:'work',to:'end',read:'',pop:'⊥',push:''}];return validate({type:'pda',states,edges})}
